            .screen-info{max-width:760px;margin:auto}.screen-info h2{margin-bottom:14px}.screen-info ol{padding-left:22px;line-height:2;color:#475569}.screen-notice{margin:18px 0;padding:14px;border:1px solid #fed7aa;border-radius:9px;color:#c2410c;background:#fff7ed;line-height:1.7}.screen-stage{position:fixed;inset:0;z-index:9999;background:#f00;color:#fff;cursor:pointer;outline:0}.screen-stage-top{position:absolute;top:22px;left:24px;right:24px;display:flex;justify-content:space-between;font-size:14px;text-shadow:0 1px 3px rgba(0,0,0,.45)}.screen-stage-help{position:absolute;bottom:24px;left:50%;transform:translateX(-50%);padding:8px 12px;border-radius:20px;background:rgba(0,0,0,.24);font-size:13px;white-space:nowrap}.screen-stage button{position:absolute;top:52px;right:24px;padding:8px 12px;border:1px solid rgba(255,255,255,.6);border-radius:8px;color:#fff;background:rgba(0,0,0,.18);cursor:pointer}@media(max-width:600px){.screen-stage-top{top:16px;left:16px;right:16px}.screen-stage button{top:45px;right:16px}.screen-stage-help{bottom:16px;font-size:11px}}
