            <script>
            (function(){const colors=[['红色','#ef4444'],['绿色','#22c55e'],['蓝色','#3b82f6'],['白色','#ffffff'],['黑色','#000000'],['灰色','#808080'],['黄色','#facc15'],['青色','#06b6d4'],['紫色','#8b5cf6'],['橙色','#f97316'],['粉色','#ec4899'],['深蓝','#1e3a8a'],['浅灰','#e5e7eb'],['暖白','#fff7ed'],['纯黑','#111827']];const stage=document.getElementById('screen-stage'),label=document.getElementById('screen-label'),count=document.getElementById('screen-count');let index=0;function paint(){const color=colors[index];stage.style.background=color[1];stage.style.color=['#ffffff','#e5e7eb','#000000','#111827'].includes(color[1])?'#111827':'#fff';label.textContent=color[0];count.textContent=(index+1)+' / '+colors.length}function stop(){stage.hidden=true;if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});}function start(){stage.hidden=false;paint();stage.focus();stage.requestFullscreen&&stage.requestFullscreen().catch(()=>{});}document.getElementById('start-test').addEventListener('click',start);document.getElementById('end-test').addEventListener('click',event=>{event.stopPropagation();stop()});stage.addEventListener('click',()=>{index=(index+1)%colors.length;paint()});document.addEventListener('keydown',event=>{if(stage.hidden)return;if(event.key==='Escape')stop();if(event.key==='ArrowRight'||event.key==='ArrowDown'){event.preventDefault();index=(index+1)%colors.length;paint()}if(event.key==='ArrowLeft'||event.key==='ArrowUp'){event.preventDefault();index=(index-1+colors.length)%colors.length;paint()}});document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&!stage.hidden)stage.hidden=true});})();
            </script>
